```python
import re
def norm_mac(s):
    hexd = re.sub(r'[^0-9A-Fa-f]', '', str(s))
    if len(hexd) != 12:
        raise ValueError(f'bad MAC: {s!r}')
    hexd = hexd.upper()
    return ':'.join(hexd[i:i+2] for i in range(0, 12, 2))
```

