def pair(host_pcie, dpus):
    clean = {k.strip(): v for k, v in dpus.items()}
    out = {}
    for d in host_pcie:
        s = (d.get('SerialNumber') or '').strip()
        if s in clean:
            out[d['Id']] = clean[s]
    return out
