import re
def parse_bdf(s):
    s = s.strip().lower()
    if s.count(':') == 1:
        s = '0000:' + s                     # add a missing domain
    m = re.fullmatch(r'([0-9a-f]{4}):([0-9a-f]{2}):([0-9a-f]{2})\.([0-7])', s)
    if not m:
        raise ValueError(s)
    return tuple(int(x, 16) for x in m.groups())
print(parse_bdf('ca:00.1'))   # (0, 202, 0, 1)
```

